ALTER TABLE catalog_products ADD COLUMN sellable INTEGER NOT NULL DEFAULT 1 CHECK(sellable IN (0,1));
ALTER TABLE catalog_products ADD COLUMN stock_mode TEXT NOT NULL DEFAULT 'own' CHECK(stock_mode IN ('own','components'));
ALTER TABLE catalog_products ADD COLUMN stock_policy TEXT NOT NULL DEFAULT 'block' CHECK(stock_policy IN ('block','negative','zero','untracked'));
ALTER TABLE catalog_products ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE catalog_components(product_id TEXT NOT NULL REFERENCES catalog_products(id),component_id TEXT NOT NULL REFERENCES catalog_products(id),factor_milli INTEGER NOT NULL CHECK(factor_milli>0),PRIMARY KEY(product_id,component_id),CHECK(product_id!=component_id)) STRICT;
CREATE INDEX catalog_components_input ON catalog_components(component_id);
CREATE TABLE inventory_stock_v2(product_id TEXT PRIMARY KEY REFERENCES catalog_products(id),qty_micro INTEGER NOT NULL CHECK(qty_micro BETWEEN -1000000000000000 AND 1000000000000000)) STRICT;
INSERT INTO inventory_stock_v2 SELECT product_id,qty_milli*1000 FROM inventory_stock;
DROP TABLE inventory_stock;
ALTER TABLE inventory_stock_v2 RENAME TO inventory_stock;
ALTER TABLE inventory_receipts ADD COLUMN qty_micro INTEGER NOT NULL DEFAULT 1 CHECK(qty_micro>0);
UPDATE inventory_receipts SET qty_micro=qty_milli*1000;
ALTER TABLE inventory_receipts DROP COLUMN qty_milli;
CREATE TABLE inventory_movements_v2(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES catalog_products(id),qty_micro INTEGER NOT NULL CHECK(qty_micro!=0),kind TEXT NOT NULL CHECK(kind IN ('receipt','sale','compensation','adjustment')),receipt_id TEXT REFERENCES inventory_receipts(id),sale_id TEXT REFERENCES sales_documents(id),actor_id TEXT NOT NULL REFERENCES admin_users(id),reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,UNIQUE(sale_id,product_id,kind),UNIQUE(receipt_id)) STRICT;
INSERT INTO inventory_movements_v2(id,product_id,qty_micro,kind,receipt_id,sale_id,actor_id,created_at) SELECT id,product_id,qty_milli*1000,CASE WHEN sale_id IS NULL THEN 'receipt' ELSE 'sale' END,receipt_id,sale_id,actor_id,created_at FROM inventory_movements;
DROP TABLE inventory_movements;
ALTER TABLE inventory_movements_v2 RENAME TO inventory_movements;
CREATE INDEX inventory_movements_product_date ON inventory_movements(product_id,created_at);
CREATE TRIGGER inventory_no_update BEFORE UPDATE ON inventory_movements BEGIN SELECT RAISE(ABORT,'ledger is append-only'); END;
CREATE TRIGGER inventory_no_delete BEFORE DELETE ON inventory_movements BEGIN SELECT RAISE(ABORT,'ledger is append-only'); END;
ALTER TABLE sales_documents ADD COLUMN details_json TEXT NOT NULL DEFAULT '';
ALTER TABLE sales_documents ADD COLUMN company_json TEXT NOT NULL DEFAULT '{}';
UPDATE sales_documents SET company_json=(SELECT json_object('name',name,'currency',currency,'currencyScale',currency_scale,'timezone',timezone) FROM admin_company WHERE singleton=1);
CREATE TABLE sales_lines_v2(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales_documents(id),product_id TEXT NOT NULL REFERENCES catalog_products(id),sku TEXT NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL,qty_milli INTEGER NOT NULL CHECK(qty_milli>0),price_minor INTEGER NOT NULL CHECK(price_minor>=0),total_minor INTEGER NOT NULL CHECK(total_minor>=0),kind TEXT NOT NULL DEFAULT 'regular',promotion_id TEXT) STRICT;
INSERT INTO sales_lines_v2(id,sale_id,product_id,sku,name,unit,qty_milli,price_minor,total_minor) SELECT lower(hex(randomblob(16))),sale_id,product_id,sku,name,unit,qty_milli,price_minor,total_minor FROM sales_lines;
DROP TABLE sales_lines;
ALTER TABLE sales_lines_v2 RENAME TO sales_lines;
CREATE INDEX sales_lines_sale ON sales_lines(sale_id);
CREATE INDEX sales_lines_product ON sales_lines(product_id);
ALTER TABLE admin_users ADD COLUMN can_manual_discount INTEGER NOT NULL DEFAULT 0 CHECK(can_manual_discount IN (0,1));
ALTER TABLE audit_entries ADD COLUMN details_json TEXT NOT NULL DEFAULT '{}';
CREATE TABLE promotion_rules(id TEXT PRIMARY KEY,name TEXT NOT NULL,version INTEGER NOT NULL,config_json TEXT NOT NULL) STRICT;
PRAGMA user_version=2;
